  it('provides discovery and instruction methods for registered tools', () => {
    const registry = new ToolRegistry();
    const tool: ToolDefinition = {
      name: 'weather',
      description: 'd',
      inputSchema: {type: 'object'},
      promptInstructions: 'use sparingly',
      examplePrompts: ['what is the weather?'],
    };

    registry.register(tool, async () => 'ok');

    expect(registry.has('weather')).toBe(true);
    expect(registry.has('missing')).toBe(false);
    expect(registry.get('weather')?.definition).toEqual(tool);
    expect(registry.get('missing')).toBeUndefined();
    expect(registry.getDefinitions()).toEqual([tool]);
    expect(registry.getPromptInstructions()).toEqual(['weather: use sparingly']);
    expect(registry.getExamplePrompts()).toEqual(['what is the weather?']);
  });

  it('logs full tool response details on successful execution', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {name: 'full', description: 'd', inputSchema: {type: 'object'}},
      async () => ({
        result: 'done',
        clientMessages: [{type: 'entry_commit', entry: {role: 'assistant', content: 'ok'}} as any],
        suppressAssistantResponse: true,
      })
    );

    const response = await registry.execute('full', {});
    expect(response).toMatchObject({
      result: 'done',
      suppressAssistantResponse: true,
    });
    expect(response.clientMessages).toHaveLength(1);
  });
});

